"""Busca híbrida (E7 do plano-benchmark.md): BM25 em Python puro e a fusão RRF no retrieve()."""
from __future__ import annotations

import math

import pytest

from app.config import get_settings
from app.rag import bm25, retrieval, vector_store

TEXTS = {
    "a::c0": "Retrieval augmented generation pipelines are evaluated with reference-free metrics.",
    "b::c0": "We propose RAGAS, a framework for the evaluation of RAG pipelines.",
    "c::c0": "Mutation testing of unit tests generated by large language models.",
}


def test_tokens_sem_acento_e_minusculos():
    assert bm25.tokenize("Avaliação do RAGAS e Defects4J!") == ["avaliacao", "do", "ragas", "e", "defects4j"]


def test_bm25_poe_primeiro_o_trecho_com_o_termo_raro():
    index = bm25.BM25Index(list(TEXTS), list(TEXTS.values()))

    ranked = index.search("Como o RAGAS avalia pipelines?", k=3)

    assert ranked[0][0] == "b::c0"
    assert {chunk_id for chunk_id, _ in ranked} == {"a::c0", "b::c0"}
    assert all(idf > 0 for idf in index.idf.values())


def test_indice_em_cache_por_colecao_e_contagem(monkeypatch):
    calls = []
    monkeypatch.setattr(bm25, "_CACHE", {})
    monkeypatch.setattr(vector_store, "collection_count", lambda: len(TEXTS))
    monkeypatch.setattr(vector_store, "get_all", lambda: calls.append(1) or {"ids": list(TEXTS),
                                                                            "documents": list(TEXTS.values())})

    first, second = bm25.index_for_collection(), bm25.index_for_collection()

    assert first is second and calls == [1]


@pytest.fixture
def hybrid_store(monkeypatch):
    """O vetor acha a e c; o BM25 acha b (a sigla), que só ele tem."""
    def query(embedding, top_k, include_embeddings=False):
        return {"ids": [["a::c0", "c::c0"]], "documents": [[TEXTS["a::c0"], TEXTS["c::c0"]]],
                "metadatas": [[{"document": "a.pdf", "page": 1}, {"document": "c.pdf", "page": 2}]],
                "distances": [[0.2, 0.4]]}

    monkeypatch.setattr(vector_store, "query", query)
    monkeypatch.setattr(vector_store, "get_by_ids", lambda ids, include_embeddings=False: {
        "ids": ids, "documents": [TEXTS[i] for i in ids], "metadatas": [{"document": "b.pdf", "page": 3}] * len(ids),
        "embeddings": [[0.3, 0.2, 0.1]] * len(ids)})
    monkeypatch.setattr(bm25, "index_for_collection", lambda: bm25.BM25Index(list(TEXTS), list(TEXTS.values())))


def test_hibrida_traz_o_trecho_que_so_o_bm25_achou_com_o_cosseno_dele(hybrid_store, monkeypatch):
    monkeypatch.setenv("RETRIEVAL_HYBRID", "true")
    monkeypatch.setenv("TOP_K", "3")
    get_settings.cache_clear()

    chunks, _ = retrieval.retrieve("What is RAGAS?")

    by_id = {c["chunk_id"]: c for c in chunks}
    assert by_id["b::c0"]["found_by"] == "bm25" and by_id["a::c0"]["found_by"] in ("vetor", "ambos")
    # O cosseno do trecho do BM25 sai do vetor guardado e da pergunta embedada pelo mock ([0,1, 0,2, 0,3]).
    expected = (0.1 * 0.3 + 0.2 * 0.2 + 0.3 * 0.1) / (math.sqrt(0.14) * math.sqrt(0.14))
    assert by_id["b::c0"]["similarity_score"] == round(expected, 4)
    assert by_id["a::c0"]["similarity_score"] == 0.8


def test_sem_a_flag_a_busca_e_a_de_sempre(hybrid_store):
    chunks, _ = retrieval.retrieve("What is RAGAS?", top_k=3)

    assert [c["chunk_id"] for c in chunks] == ["a::c0", "c::c0"]
    assert all("found_by" not in c for c in chunks)
